import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`podcast-generator`,heroTitle:`Generate your podcast in minutes`,heroSubtitle:`Perplexity Computer researches your topic, writes a natural script, and produces a 5-minute podcast episode — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Researching your topic and gathering key talking points`,`Writing a conversational podcast script with natural flow`,`Generating voice audio with pacing, tone, and transitions`,`Final episode with script, audio, and show notes — ready to publish`],generatingSteps:[`Analyzing your topic to identify the most compelling angles and sources`,`Designing an agent to write a structured, conversational podcast script`,`Configuring voice generation, pacing, and audio production settings`,`Setting up show notes, timestamps, and export-ready deliverables`],featureSectionTitle:`From topic to podcast episode`,featureCardTitles:[`Connects to your creative stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Drive, Notion, Dropbox Sign, Google Docs, Canva — Computer plugs into your tools so research, scripts, and audio flow into one workflow.`,`Full podcast script. 5-minute audio episode. Timestamped show notes. Episode title and description. Social media snippets for promotion.`],capabilitySectionTitle:`Your podcast producer, on autopilot`,capabilitySectionSubtitle:`Pick a topic, step away, come back to a publish-ready podcast episode.`,capabilityCards:[{title:`Deep Research`,description:`Computer can research any topic across the web — pulling key facts, expert perspectives, and compelling angles to build a well-informed episode.`},{title:`Script Writing`,description:`Computer can write a natural, conversational podcast script — with hooks, transitions, and a clear narrative arc tuned to a 5-minute runtime.`},{title:`Audio Production`,description:`Computer can generate voice audio with natural pacing, tone shifts, and smooth transitions — producing a polished episode ready for any platform.`},{title:`Connect Your Tools`,description:`Computer can export to Google Drive, Notion, Google Docs, and more — build workflows that store scripts, audio, and show notes where you need them.`},{title:`Remember Your Style`,description:`Computer can remember your preferred tone, format, intro style, and past episodes — so every new podcast sounds consistent with your brand.`},{title:`Schedule & Alert`,description:`Computer can generate episodes on a recurring schedule and notify you when new episodes are ready for review and publishing.`}]});export{t as default};
